mapper.select:
SELECT md.`name` deptName, mds.id deptSubId, mds.`name` deptSubName, dwp.`date` `date`, d.`name` doctorName, dwp.id workPlanId FROM doctor_work_plan dwp JOIN doctor d ON dwp.doctor_id = d.id JOIN medical_dept_sub mds ON mds.id = dwp.dept_sub_id JOIN medical_dept md ON mds.dept_id = md.id WHERE dwp.`date` BETWEEN STR_TO_DATE('${startDate}', '%Y-%m-%d') AND STR_TO_DATE('${endDate}', '%Y-%m-%d')
AND mds.dept_id = #{deptId}
AND d.`name` LIKE "%${doctorName}%"

SELECT id
FROM doctor_work_plan
WHERE doctor_id = #{doctorId}
  AND dept_sub_id = #{deptSubId}
  AND date = STR_TO_DATE('${date}', '%Y-%m-%d')
